import {freshState,freshMatch,uid,elapsed,score,minutes,start,pause,setLineup,undo,validateState} from './model.js';
const KEY='zijlijn-v1', $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
let state=freshState(), storageError='', tab=location.hash.slice(1)||'wedstrijd', toastTimer, wakeLock;
try {const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch(e){storageError='Je opgeslagen gegevens konden niet worden geladen. Download eerst een herstelbestand via Mijn team. Nieuwe wijzigingen worden nog niet opgeslagen.';}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>state.players.find(p=>p.id===id)?.name||'Lege plek';
const initials=n=>n.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const clock=ms=>`${Math.floor(ms/60000).toString().padStart(2,'0')}:${Math.floor(ms/1000%60).toString().padStart(2,'0')}`;
const present=()=>state.players.filter(p=>p.present);
const bench=()=>present().filter(p=>!state.match.lineup.includes(p.id));
const dateLabel=m=>m.date?new Date(m.date).toLocaleString('nl-NL',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Nog geen aftraptijd';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function save(){if(storageError)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageError='Opslaan lukt niet. Je gegevens staan nu alleen in dit scherm. Maak een back-up via Mijn team.';toast(storageError);}}
function update(){save();render();}
function modal(title,html){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Sluiten">×</button></div>${html}`;if(!dialog.open)dialog.showModal();}
function confirmAction(title,text,action,label='Bevestigen'){modal(title,`<p>${text}</p><div class="row"><button data-action="close">Annuleren</button><button class="primary" data-action="${action}">${label}</button></div>`);}
function render(){
 if(!['wedstrijd','opstelling','team'].includes(tab))tab='wedstrijd';
 document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});
 app.innerHTML=(storageError?`<div class="warning" role="alert">${esc(storageError)}</div>`:'')+(tab==='wedstrijd'?matchView():tab==='opstelling'?lineupView():teamView());tick();
}
function pitch(){return `<div class="pitch" aria-label="Opstelling 1-2-2-1">${state.match.lineup.map((id,i)=>`<button class="position pos-${i} ${id?'':'empty'}" data-action="position" data-index="${i}" ${state.match.status==='ended'?'disabled':''} aria-label="${['Keeper','Linksachter','Rechtsachter','Linksmidden','Rechtsmidden','Spits'][i]}: ${esc(name(id))}"><span class="shirt">${id?esc(initials(name(id))):'+'}</span><span>${id?esc(name(id)):['Keeper','Linksachter','Rechtsachter','Linksmidden','Rechtsmidden','Spits'][i]}</span></button>`).join('')}</div>`;}
function lineupCard(){return `<section class="card"><div class="card-head"><h2>Op het veld</h2><span class="pill">${state.match.lineup.filter(Boolean).length} / 6</span></div>${pitch()}<div class="subtle-row"><h3>Wisselbank</h3><span class="small muted">${bench().length} spelers</span></div><div class="bench">${bench().map(p=>`<button data-action="bench" data-id="${esc(p.id)}" ${state.match.status==='ended'?'disabled':''}>${esc(p.name)}</button>`).join('')}</div>${state.players.length===0?'<p class="hint">Voeg je spelers toe bij Mijn team en tik op een positie.</p>':'<p class="hint">Tik op een positie of bankspeler om te wisselen.</p>'}</section>`;}
function matchView(){const m=state.match,s=score(m),live=m.status==='live',ended=m.status==='ended';return `<div class="heading"><div><p class="eyebrow">Aan de zijlijn</p><h1>Wedstrijddag</h1></div><button data-action="edit-match" class="ghost" ${ended?'disabled':''}>Wedstrijd instellen</button></div><div class="grid"><div><section class="card scoreboard"><div class="card-head"><span class="small muted">${esc(dateLabel(m))} · ${m.home?'Thuis':'Uit'}</span><span class="pill">${ended?'Afgelopen':live?'Bezig':'Voor de aftrap'}</span></div><div class="score-line"><div><span class="team-name">Nieuwerkerk<br>JO10-8</span><strong class="score-value">${s.us}</strong><button class="goal us" data-action="goal-us" ${!live?'disabled':''}>+ Doelpunt</button></div><span class="separator">:</span><div><span class="team-name">${esc(m.opponent||'Tegenstander')}<br><span class="muted small">${m.home?'Uit':'Thuis'}</span></span><strong class="score-value">${s.them}</strong><button class="goal" data-action="goal-them" ${!live?'disabled':''}>+ Doelpunt</button></div></div><div class="timer"><div class="clock" id="clock">00:00</div><p class="timer-label" id="timer-label"></p><div class="row"><button class="primary" data-action="clock" ${ended?'disabled':''}>${m.startedAt!==null?'Ⅱ Pauze':m.status==='ready'?'▶ Aftrap':'▶ Hervatten'}</button>${m.half===1&&!ended?`<button class="ghost" data-action="second-half" ${!live?'disabled':''}>2e helft</button>`:`<button class="ghost" data-action="finish" ${ended?'disabled':''}>Afronden</button>`}</div></div></section><div class="subtle-row" style="margin:-12px 0 20px"><button class="text-button" data-action="undo" ${!m.events.length||ended?'disabled':''}>Laatste actie herstellen</button><button class="text-button" data-action="${ended?'new-match':'finish'}" ${m.status==='ready'?'disabled':''}>${ended?'Nieuwe wedstrijd':'Wedstrijd afronden'}</button></div><section class="card"><div class="card-head"><h2>Wedstrijdverloop</h2><span class="small muted">${m.events.length} acties</span></div>${timeline()}</section></div><div>${lineupCard()}<section class="card"><div class="card-head"><h2>Speeltijd</h2><span class="small muted">Deze wedstrijd</span></div>${playingTimes()}</section></div></div><p class="offline-note" id="connection"></p>`;}
function eventDescription(e){if(e.type==='goal')return `<strong>Doelpunt ${e.side==='us'?'Nieuwerkerk':esc(state.match.opponent||'tegenstander')}</strong>`;const out=e.before.filter(id=>id&&!e.lineup.includes(id)),incoming=e.lineup.filter(id=>id&&!e.before.includes(id));return `<strong>${out.length||incoming.length?'Wissel':'Posities gewisseld'}</strong><small>${incoming.length?'In: '+incoming.map(id=>esc(name(id))).join(', '):''}${incoming.length&&out.length?' · ':''}${out.length?'Uit: '+out.map(id=>esc(name(id))).join(', '):''}</small>`;}
function timeline(){return state.match.events.length?`<ol class="timeline">${[...state.match.events].reverse().map(e=>`<li><time>${clock(e.at)}</time><div>${eventDescription(e)}</div></li>`).join('')}</ol>`:'<div class="empty-state">Klaar voor de aftrap.<br>Doelpunten en wissels verschijnen hier.</div>';}
function playingTimes(){const activeIds=new Set([...present().map(p=>p.id),...state.match.initialLineup,...state.match.events.filter(e=>e.type==='lineup').flatMap(e=>e.lineup)]);const players=state.players.filter(p=>activeIds.has(p.id));return players.length?players.map(p=>`<div class="player-row"><span class="avatar">${esc(initials(p.name))}</span><div class="player-info"><strong>${esc(p.name)}</strong><small>${state.match.lineup.includes(p.id)?(state.match.lineup[0]===p.id?'Keeper':'Op het veld'):p.present?'Op de bank':'Afwezig'}</small><div class="bar"><span data-bar="${esc(p.id)}"></span></div></div><span class="player-time" data-time="${esc(p.id)}">00:00</span></div>`).join(''):'<div class="empty-state">Voeg eerst je spelers toe.</div>';}
function lineupView(){return `<div class="single"><div class="heading"><div><p class="eyebrow">Iedereen zijn plek</p><h1>De opstelling</h1></div><span class="pill">1–2–2–1</span></div>${lineupCard()}<section class="card"><h2>Speeltijd per speler</h2><p class="hint">De klok telt alleen mee wanneer de wedstrijd loopt. Herstel je een wissel, dan wordt de speeltijd opnieuw berekend.</p>${playingTimes()}</section></div>`;}
function teamView(){const m=state.match,locked=m.status!=='ready';return `<div class="single"><div class="heading"><div><p class="eyebrow">vv Nieuwerkerk JO10-8</p><h1>Mijn team</h1></div><span class="pill">${present().length} aanwezig</span></div><section class="card"><div class="card-head"><h2>Spelers</h2><span class="small muted">${state.players.length} totaal</span></div><form id="add-player" class="form-inline"><input name="name" aria-label="Naam nieuwe speler" placeholder="Voornaam speler" maxlength="40" required><button type="submit" class="primary">Toevoegen</button></form>${!state.players.length?'<div class="empty-state">Begin met de voornamen van je team.<br>Je gegevens blijven op dit toestel.</div>':state.players.map(p=>`<div class="player-row"><span class="avatar">${esc(initials(p.name))}</span><div class="player-info"><strong>${esc(p.name)}</strong><label class="check small muted"><input type="checkbox" data-present="${esc(p.id)}" ${p.present?'checked':''} ${locked?'disabled':''}> Aanwezig</label></div><button class="text-button" data-action="edit-player" data-id="${esc(p.id)}">Bewerk</button></div>`).join('')}${locked?'<p class="hint">Aanwezigheid en verwijderen zijn weer beschikbaar bij een nieuwe wedstrijd. Spelers toevoegen kan altijd.</p>':''}</section><section class="card"><h2>Volgende tegenstander</h2><p class="muted">Neem het programma over uit voetbal.nl. Automatisch ophalen is nog niet gekoppeld.</p><div class="row"><button data-action="edit-match" ${m.status==='ended'?'disabled':''}>Wedstrijd invoeren</button><a href="https://www.voetbal.nl/" target="_blank" rel="noopener noreferrer">Open voetbal.nl ↗</a></div></section><section class="card"><h2>Gegevens & back-up</h2><p class="muted">Opgeslagen in deze browser. Maak af en toe een back-up; bij wissen van browsergegevens raak je anders je team en wedstrijden kwijt.</p><div class="row"><button data-action="export">Back-up opslaan</button><button data-action="import">Back-up terugzetten</button></div>${storageError?'<button class="wide" data-action="recovery">Oorspronkelijke opslag downloaden</button>':''}<input type="file" id="import-file" accept="application/json,.json" hidden><details><summary>Gebruiken als app</summary><p class="small muted">Open de app via de gehoste website. Op iPhone: Safari → Deel → Zet op beginscherm. Op Android: browsermenu → App installeren of Toevoegen aan startscherm. Open de app eerst met internet en wacht tot ‘Offline beschikbaar’ onder de wedstrijd staat.</p><p class="small muted">Gebruik tijdens de wedstrijd één tabblad. Als je de app sluit terwijl de klok loopt, telt de tijd door. Druk bij rust of een time-out op Pauze.</p></details></section><section class="card"><div class="card-head"><h2>Vorige wedstrijden</h2><span class="small muted">${state.history.length}</span></div>${state.history.length?[...state.history].reverse().map(h=>{const s=score(h.match);return `<div class="history-row"><div>${esc(h.match.opponent||'Tegenstander')}<div class="small muted">${esc(dateLabel(h.match))}</div></div><strong>${s.us} – ${s.them}</strong></div>`;}).join(''):'<p class="muted small">Een afgeronde wedstrijd blijft hier bewaard.</p>'}</section></div>`;}
function tick(){const m=state.match,t=elapsed(m),c=$('#clock');if(c)c.textContent=clock(t);const l=$('#timer-label');if(l)l.textContent=`${m.half}e helft · ${m.halfMinutes} min per helft${m.startedAt===null?' · Klok staat stil':''}${t>=m.half*m.halfMinutes*60000?' · Richttijd bereikt':''}`;const times=minutes(m);document.querySelectorAll('[data-time]').forEach(el=>el.textContent=clock(times[el.dataset.time]||0));document.querySelectorAll('[data-bar]').forEach(el=>el.style.width=`${t?Math.min(100,(times[el.dataset.bar]||0)/t*100):0}%`);const connection=$('#connection');if(connection)connection.textContent=!navigator.onLine?'Offline · gegevens blijven op dit toestel':offlineReady?'Offline beschikbaar · opgeslagen op dit toestel':'Opgeslagen op dit toestel';}
function choosePosition(index){const m=state.match;if(m.status==='ended')return;modal(['Keeper','Linksachter','Rechtsachter','Linksmidden','Rechtsmidden','Spits'][index],`<p class="muted small">Kies een speler. Een speler die al in het veld staat, ruilt van positie.</p>${present().map(p=>`<button class="choice" data-action="assign" data-index="${index}" data-id="${esc(p.id)}"><span class="avatar">${esc(initials(p.name))}</span>${esc(p.name)}<small>${m.lineup.includes(p.id)?'Veld':'Bank'}</small></button>`).join('')}${m.lineup[index]?`<button class="wide ghost" data-action="assign" data-index="${index}" data-id="">Positie leegmaken</button>`:''}${!present().length?'<p>Voeg eerst aanwezige spelers toe bij Mijn team.</p>':''}`);}
function assign(index,id){const m=state.match;if(id&&!present().some(p=>p.id===id))throw Error('Deze speler is niet aanwezig.');const line=[...m.lineup];if(line[index]===id){dialog.close();return;}const oldIndex=line.indexOf(id);if(id&&oldIndex!==-1)line[oldIndex]=line[index];line[index]=id||null;setLineup(m,line);dialog.close();update();toast(m.status==='ready'?'Opstelling opgeslagen':'Wissel opgeslagen');}
function editMatch(){const m=state.match;modal('Wedstrijd instellen',`<form id="match-form" class="stack"><label>Tegenstander<input name="opponent" value="${esc(m.opponent)}" maxlength="80" placeholder="Bijvoorbeeld: tegenstander JO10-…"></label><label>Aftrap<input type="datetime-local" name="date" value="${esc(m.date)}"></label><label>Thuis of uit<select name="home"><option value="true" ${m.home?'selected':''}>Thuis</option><option value="false" ${!m.home?'selected':''}>Uit</option></select></label><label>Minuten per helft<input type="number" name="halfMinutes" min="1" max="60" value="${m.halfMinutes}" required></label><button class="primary" type="submit">Opslaan</button></form>`);}
async function keepAwake(){try{if(state.match.startedAt!==null&&document.visibilityState==='visible'&&navigator.wakeLock&&!wakeLock){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>wakeLock=null);}else if(state.match.startedAt===null&&wakeLock){await wakeLock.release();wakeLock=null;}}catch{}}
function download(text,filename){const u=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
let pendingImport=null;
const actions={
 'close':()=>dialog.close(), 'edit-match':editMatch,
 'position':b=>choosePosition(Number(b.dataset.index)),
 'assign':b=>assign(Number(b.dataset.index),b.dataset.id),
 'bench':b=>{modal(`${esc(name(b.dataset.id))} inbrengen`,state.match.lineup.map((id,i)=>`<button class="choice" data-action="assign" data-index="${i}" data-id="${esc(b.dataset.id)}">${id?'Voor '+esc(name(id)):'Op lege positie '+(i+1)}</button>`).join(''));},
 'clock':()=>{const m=state.match;if(m.status==='ended')return;if(m.startedAt!==null)pause(m);else {if(m.status==='ready'&&!m.lineup.some(Boolean)){toast('Zet eerst spelers in de opstelling.');tab='opstelling';location.hash=tab;render();return;}start(m);}keepAwake();update();},
 'goal-us':()=>goal('us'),'goal-them':()=>goal('them'),
 'undo':()=>{if(undo(state.match)){update();toast('Laatste actie hersteld');}},
 'second-half':()=>confirmAction('Tweede helft','De klok wordt gepauzeerd. Tik bij de aftrap van de tweede helft op Hervatten. De totale speeltijd blijft behouden.','confirm-half','Naar 2e helft'),
 'confirm-half':()=>{pause(state.match);state.match.half=2;keepAwake();dialog.close();update();},
 'finish':()=>confirmAction('Wedstrijd afronden','De klok stopt en de wedstrijd wordt bewaard. Controleer eerst de score en de wissels.','confirm-finish','Afronden'),
 'confirm-finish':()=>{const m=state.match;if(m.status!=='live')return;pause(m);m.status='ended';state.history.push({match:structuredClone(m),players:state.players.map(p=>({id:p.id,name:p.name}))});keepAwake();dialog.close();update();toast('Wedstrijd bewaard');},
 'new-match':()=>confirmAction('Nieuwe wedstrijd','Je team blijft bewaard. De score, klok en opstelling beginnen opnieuw.','confirm-new','Nieuwe wedstrijd'),
 'confirm-new':()=>{if(state.match.status!=='ended')return;state.match=freshMatch();dialog.close();update();},
 'edit-player':b=>{const p=state.players.find(p=>p.id===b.dataset.id);modal('Speler bewerken',`<form id="player-form" data-id="${esc(p.id)}" class="stack"><label>Voornaam<input name="name" value="${esc(p.name)}" maxlength="40" required></label><button type="submit" class="primary">Opslaan</button></form>${state.match.status==='ready'?`<button class="text-button danger" data-action="delete-player" data-id="${esc(p.id)}">Speler verwijderen</button>`:''}`);},
 'delete-player':b=>{const id=b.dataset.id;if(state.match.status!=='ready')return;state.players=state.players.filter(p=>p.id!==id);setLineup(state.match,state.match.lineup.map(x=>x===id?null:x));dialog.close();update();},
 'export':()=>{const snapshot=structuredClone(state);pause(snapshot.match);download(JSON.stringify(snapshot,null,2),`zijlijn-backup-${new Date().toISOString().slice(0,10)}.json`);},
 'import':()=>$('#import-file').click(),
 'confirm-import':()=>{if(!pendingImport)return;state=pendingImport;pendingImport=null;storageError='';pause(state.match);keepAwake();dialog.close();update();toast('Back-up teruggezet. De klok staat op pauze.');},
 'recovery':()=>{try{download(localStorage.getItem(KEY)||'null','zijlijn-herstelbestand.json');}catch{toast('De browser geeft geen toegang tot de opslag.');}}
};
function goal(side){const m=state.match;if(m.status!=='live')return;m.events.push({id:uid(),type:'goal',side,at:elapsed(m)});update();toast(side==='us'?'Doelpunt Nieuwerkerk!':'Doelpunt tegenstander');}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-tab]');if(nav){tab=nav.dataset.tab;location.hash=tab;render();return;}const b=e.target.closest('[data-action]');if(b&&!b.disabled){try{actions[b.dataset.action]?.(b);}catch(err){toast(err.message);}}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='add-player'){const n=String(d.get('name')).trim();if(!n)return;if(state.players.length>=100){toast('Maximaal 100 spelers.');return;}state.players.push({id:uid(),name:n,present:true});update();$('#add-player input').focus();}if(f.id==='match-form'){const m=state.match;if(m.status==='ended')return;const duration=Number(d.get('halfMinutes'));if(!Number.isInteger(duration)||duration<1||duration>60)return;Object.assign(m,{opponent:String(d.get('opponent')).trim(),date:String(d.get('date')),home:d.get('home')==='true',halfMinutes:duration});dialog.close();update();}if(f.id==='player-form'){const n=String(d.get('name')).trim();if(!n)return;state.players.find(p=>p.id===f.dataset.id).name=n;dialog.close();update();}});
document.addEventListener('change',async e=>{if(e.target.dataset.present){if(state.match.status!=='ready')return;const p=state.players.find(p=>p.id===e.target.dataset.present);p.present=e.target.checked;if(!p.present)setLineup(state.match,state.match.lineup.map(x=>x===p.id?null:x));update();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Bestand is te groot (maximaal 5 MB).');pendingImport=validateState(JSON.parse(await file.text()));if(pendingImport.match.startedAt!==null){pendingImport.match.elapsed=elapsed(pendingImport.match);pendingImport.match.startedAt=null;}confirmAction('Back-up terugzetten',`Dit vervangt je huidige gegevens door ${pendingImport.players.length} spelers en ${pendingImport.history.length} bewaarde wedstrijden. Sla zo nodig eerst je huidige back-up op.`,'confirm-import','Terugzetten');}catch(err){pendingImport=null;toast(err.message);}e.target.value='';}});
window.addEventListener('hashchange',()=>{tab=location.hash.slice(1);render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));dialog.close();render();toast('Gegevens bijgewerkt vanuit een ander tabblad.');}catch{}}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();keepAwake();}});
window.addEventListener('online',tick);window.addEventListener('offline',tick);
let offlineReady=false;
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;tick();}).catch(()=>{});}
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(modelContext.registerTool({name:'read_match',title:'Wedstrijd bekijken',description:'Lees score, klok, opstelling en speeltijd van de huidige wedstrijd.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Geen parameters toegestaan.');return {opponent:state.match.opponent,status:state.match.status,score:score(state.match),elapsedMs:elapsed(state.match),players:state.players.map(p=>({name:p.name,onField:state.match.lineup.includes(p.id),playedMs:minutes(state.match)[p.id]||0}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
render();setInterval(tick,1000);keepAwake();
